<script>
    import { onMount } from 'svelte';
    import { round } from '$lib/utils/helper';
    import { getTeamFromTeamManagers } from '$lib/utils/helperFunctions/universalFunctions';
    import { matchupInjurySentence } from './injuryStoryUtils.js';
    export let matchupArray=[]; export let players={}; export let displayWeek; export let year; export let leagueTeamManagers;
    let playerSpotlightLabel='Player Of The Night'; let liveInjuries={};
    const liveStarterIds=()=>[...new Set((matchupArray||[]).flatMap(m=>(m||[]).flatMap(e=>e?.starters||[])).filter(id=>id&&id!=0).map(String))];
    const refreshInjuries=async()=>{try{const ids=liveStarterIds(),query=ids.length?`&ids=${encodeURIComponent(ids.join(','))}`:'';const res=await fetch(`/api/player_injuries?t=${Date.now()}${query}`,{cache:'no-store'});if(res.ok)liveInjuries=await res.json();}catch(error){}};
    onMount(()=>{const updateLabel=()=>{const now=new Date();playerSpotlightLabel=now.getDay()===0&&now.getHours()>=9&&now.getHours()<17?'Player Of The Day':'Player Of The Night';};updateLabel();refreshInjuries();const labelTimer=setInterval(updateLabel,60000),injuryTimer=setInterval(refreshInjuries,120000);return()=>{clearInterval(labelTimer);clearInterval(injuryTimer);};});
    $: newsroomPlayers=(()=>{const merged={...players};for(const[id,injury]of Object.entries(liveInjuries||{}))merged[id]={...(players?.[id]||{}),...injury};return merged;})();
    const numericRound=v=>Number(round(Number(v)||0)); const sum=(v=[])=>v.reduce((t,x)=>t+(Number(x)||0),0); const actual=e=>numericRound(sum(e?.points||[]));
    const safeTeam=id=>{try{return getTeamFromTeamManagers(leagueTeamManagers,Number(id),year)||{name:`Team ${id}`};}catch(error){return{name:`Team ${id}`};}};
    const projection=e=>numericRound((e?.starters||[]).reduce((t,id)=>{const v=Number(players?.[id]?.wi?.[displayWeek]?.p);return t+(Number.isFinite(v)?v:0);},0));
    const playerName=id=>{const p=players?.[id];if(!p)return`Player ${id}`;if(p.pos==='DEF')return p.ln||p.fn||String(id).toUpperCase();return`${p.fn||''} ${p.ln||''}`.trim()||`Player ${id}`;};
    const starterPerformances=e=>{const starters=e?.starters||[],points=e?.points||[];return starters.map((id,i)=>{if(!id||id==0)return null;const scored=Number(points[i]||0),projected=Number(players?.[id]?.wi?.[displayWeek]?.p)||0;return{id,name:playerName(id),points:numericRound(scored),projection:numericRound(projected),delta:numericRound(scored-projected)};}).filter(Boolean);};
    const topScorer=e=>[...starterPerformances(e)].sort((a,b)=>b.points-a.points)[0]||null;
    const bestPerformance=e=>[...starterPerformances(e)].filter(p=>p.points>0).sort((a,b)=>b.delta-a.delta||b.points-a.points)[0]||null;
    const biggestDisappointment=e=>[...starterPerformances(e)].filter(p=>p.projection>=8).sort((a,b)=>a.delta-b.delta)[0]||null;
    const performanceSentence=(e,teamName)=>{const best=bestPerformance(e),cold=biggestDisappointment(e),parts=[];if(best&&best.delta>=5)parts.push(`${best.name} is detonating the projection with ${best.points} points, already ${numericRound(best.delta)} above expectations and giving ${teamName} a jolt`);else if(best&&best.points>=12)parts.push(`${best.name} is dragging ${teamName} forward with ${best.points} points and has become the engine of this matchup`);if(cold&&cold.points>0&&cold.delta<=-8)parts.push(`${cold.name} is becoming a problem, sitting ${numericRound(Math.abs(cold.delta))} below projection and leaving valuable points on the table`);return parts.length?`${parts.join(', while ')}.`:'';};
    const matchupVariant=(a,b)=>(Number(a?.roster_id||0)*7+Number(b?.roster_id||0)*11+Number(displayWeek||0))%4; const pick=(a,b,v)=>v[matchupVariant(a,b)];
    const upsetSentence=(a,b,l,f,m,pm,early)=>pick(a,b,[`${l.team.name} has ripped up the pregame script. The ${pm}-point underdog now owns a ${m}-point lead over ${f.team.name}${early?', and the favorite is already feeling the pressure':', with the upset sirens getting louder by the minute'}.`,`${l.team.name} came in as the underdog and apparently took that personally. A ${m}-point advantage has ${f.team.name} chasing the game, and the ${pm}-point favorite suddenly has a real fight on its hands.`,`The favorite is in trouble. ${l.team.name} has jumped ${f.team.name} and built a ${m}-point lead despite entering the week ${pm} points behind in the projection. What looked comfortable before kickoff is anything but comfortable now.`,`${l.team.name} is crashing the party. The projected underdog has stormed ahead by ${m}, leaving ${f.team.name} staring at the scoreboard and wondering how quickly this matchup got away from the script.`]);
    const leadDangerSentence=(a,b,l,t,m)=>pick(a,b,[`${l.team.name} is hanging onto the lead by a thread. Only ${m} points separate these teams, and one touchdown, one long catch, or one busted projection could flip the entire matchup in seconds.`,`${l.team.name} has the edge, but this thing is wobbling. ${t.team.name} is only ${m} points back, close enough that one scoring burst could erase the lead in a heartbeat.`,`Nobody should feel comfortable here. ${l.team.name} leads by just ${m}, and ${t.team.name} is sitting right on the doorstep waiting for one player to crack this open.`,`${l.team.name} is in front, but barely. A ${m}-point cushion is nothing in fantasy football, and ${t.team.name} is one big play away from turning the entire matchup upside down.`]);
    const earlyEdgeSentence=(a,b,l,t,m,f)=>pick(a,b,f===l?[`${l.team.name} has taken the first bite out of this matchup with a ${m}-point lead. The favorite is following the script so far, but this is still early enough for the entire story to swing.`,`${l.team.name} is out in front by ${m}, exactly where the projection suggested it might be. Still, ${t.team.name} has plenty of runway to punch back.`,`${l.team.name} has opened the door with a ${m}-point advantage. The favorite has control for now, but nothing about this lead feels permanent yet.`,`${l.team.name} has the early scoreboard edge at ${m} points. It is the expected team on top, but ${t.team.name} is still close enough to make this interesting fast.`]:[`${l.team.name} has grabbed a ${m}-point head start and immediately put the projection on notice. ${t.team.name} was expected to have the edge, but now it is the one being asked to respond.`,`${l.team.name} has drawn first blood with a ${m}-point advantage. That is not how the projections had this starting, and ${t.team.name} is already being forced off script.`,`${l.team.name} has jumped ahead by ${m}, giving the projected favorite an early problem to solve. ${t.team.name} still has time, but the first punch has landed.`,`${l.team.name} has stolen the early momentum with a ${m}-point lead. The projection favored ${t.team.name}, but the scoreboard is telling a different story right now.`]);
    const deadEvenSentence=(a,b,o,t)=>pick(a,b,[`${o.team.name} and ${t.team.name} are locked in a dead heat. Neither side has blinked, and this matchup is sitting on a knife's edge waiting for one player to swing the entire night.`,`Nothing separates ${o.team.name} and ${t.team.name}. The scoreboard is frozen even, turning every remaining touch, catch and touchdown into a potential game-breaker.`,`${o.team.name} and ${t.team.name} are staring each other down with the score dead even. Somebody has to blink first, and right now there is absolutely no margin for error.`,`We have a full-on standoff. ${o.team.name} and ${t.team.name} cannot shake each other, and the next scoring burst could completely change the mood of this matchup.`]);
    const blowoutSentence=(a,b,l,t,m)=>pick(a,b,[`${l.team.name} is turning this into a demolition. The lead has exploded to ${m}, and ${t.team.name} is running out of room to stop this from becoming the week's ugliest result.`,`${l.team.name} is pouring it on. A ${m}-point gap has left ${t.team.name} buried, and this is starting to look less like a matchup and more like a public beating.`,`${l.team.name} has blown the doors off this matchup with a ${m}-point advantage. ${t.team.name} needs something bordering on ridiculous to make this competitive again.`,`${l.team.name} is putting on a clinic while ${t.team.name} watches the deficit balloon to ${m}. Unless something changes fast, this one is headed straight toward blowout territory.`]);
    const comebackSentence=(a,b,l,t,m)=>pick(a,b,[`${t.team.name} came in as the projected favorite, but now the night is turning into survival mode. It trails ${l.team.name} by ${m}, and every remaining starter suddenly carries comeback pressure.`,`${t.team.name} was supposed to control this matchup. Instead, the favorite is ${m} points down and staring at a comeback mission while ${l.team.name} tries to keep the door slammed shut.`,`The script has flipped on ${t.team.name}. The projected favorite now trails ${l.team.name} by ${m}, turning every player left in the lineup into a potential rescue mission.`,`${t.team.name} has work to do. A ${m}-point deficit has transformed the favorite into the hunter, and ${l.team.name} now gets to see whether it can survive the charge.`]);
    const takingControlSentence=(a,b,l,t,m)=>pick(a,b,[`${l.team.name} is starting to put a boot on this matchup. The advantage has climbed to ${m}, forcing ${t.team.name} to chase a major swing before this gets away for good.`,`${l.team.name} is tightening its grip. The lead has stretched to ${m}, and ${t.team.name} is quickly reaching the point where ordinary production will not be enough.`,`${l.team.name} has seized control and is making ${t.team.name} chase. At ${m} points, the gap is big enough to hurt but still close enough to make the next wave of players matter.`,`${l.team.name} is starting to own the scoreboard. A ${m}-point cushion has shifted the pressure squarely onto ${t.team.name}, which now needs a spark before the door starts closing.`]);
    const buildNarrative=(a,b,one,two,leader,trailer,favorite,margin,projectedMargin,isUpset,top)=>{let tag='📈 EARLY EDGE',tone='normal';const paragraphs=[],isEarly=one.score+two.score<35;if(!leader){tag='⚔️ DEAD EVEN';tone='close';paragraphs.push(deadEvenSentence(a,b,one,two));}else if(isUpset){tag='🚨 UPSET BREWING';tone='upset';paragraphs.push(upsetSentence(a,b,leader,favorite,margin,projectedMargin,isEarly));}else if(margin>=30){tag='💥 BLOWOUT DEVELOPING';tone='blowout';paragraphs.push(blowoutSentence(a,b,leader,trailer,margin));}else if(margin<=5){tag='😬 LEAD IN DANGER';tone='close';paragraphs.push(leadDangerSentence(a,b,leader,trailer,margin));}else if(favorite===trailer&&margin>=8){tag='🔥 COMEBACK WATCH';tone='comeback';paragraphs.push(comebackSentence(a,b,leader,trailer,margin));}else if(margin>=20){tag='🔥 TAKING CONTROL';tone='hot';paragraphs.push(takingControlSentence(a,b,leader,trailer,margin));}else paragraphs.push(earlyEdgeSentence(a,b,leader,trailer,margin,favorite));const leaderEntry=leader===one?a:b,trailerEntry=leader===one?b:a;if(leader){const lp=performanceSentence(leaderEntry,leader.team.name),tp=performanceSentence(trailerEntry,trailer.team.name);if(lp)paragraphs.push(lp);else if(top?.points>0)paragraphs.push(`${top.name} is setting the tone with ${top.points} points and is currently the biggest reason this matchup has tilted.`);if(tp)paragraphs.push(tp);}else if(top?.points>0)paragraphs.push(`${top.name} leads all starters with ${top.points} points, but even that has not been enough to break the stalemate.`);const injuryText=matchupInjurySentence(a,b,newsroomPlayers,displayWeek,one.team.name,two.team.name,'live').trim();if(injuryText)paragraphs.push(injuryText);if(leader&&margin<=10)paragraphs.push(`This one is nowhere near safe. ${leader.team.name} has the scoreboard edge, but ${trailer.team.name} is still one explosive performance away from ripping the lead away.`);else if(leader&&margin>=20)paragraphs.push(`${trailer.team.name} now needs something dramatic from the players still to come. Meanwhile, ${leader.team.name} can start thinking about slamming the door shut.`);return{tag,tone,text:paragraphs.join(' ')};};
    const makeUpdate=matchup=>{const a=matchup?.[0],b=matchup?.[1];if(!a||!b)return null;const one={team:safeTeam(a.roster_id),score:actual(a),projection:projection(a)},two={team:safeTeam(b.roster_id),score:actual(b),projection:projection(b)},topA=topScorer(a),topB=topScorer(b),top=!topA?topB:!topB?topA:topA.points>=topB.points?topA:topB,leader=one.score===two.score?null:one.score>two.score?one:two,trailer=leader===one?two:one,favorite=one.projection===two.projection?null:one.projection>two.projection?one:two,margin=numericRound(Math.abs(one.score-two.score)),projectedMargin=numericRound(Math.abs(one.projection-two.projection)),isUpset=leader&&favorite&&leader!==favorite&&projectedMargin>=3,narrative=buildNarrative(a,b,one,two,leader,trailer,favorite,margin,projectedMargin,isUpset,top);return{teamOne:one.team,teamTwo:two.team,scoreOne:one.score,scoreTwo:two.score,projectionOne:one.projection,projectionTwo:two.projection,top,tag:narrative.tag,tone:narrative.tone,text:narrative.text,margin,leader,trailer,favorite,total:one.score+two.score,variant:matchupVariant(a,b)};};
    $: updates=(matchupArray||[]).map(makeUpdate).filter(Boolean); $: highest=updates.flatMap(i=>[{team:i.teamOne,points:i.scoreOne},{team:i.teamTwo,points:i.scoreTwo}]).sort((a,b)=>b.points-a.points)[0]; $: closest=[...updates].sort((a,b)=>a.margin-b.margin)[0]; $: topPlayer=updates.map(i=>i.top).filter(Boolean).sort((a,b)=>b.points-a.points)[0]; $: upset=updates.find(i=>i.tone==='upset');
    const storyPick=(item,offset,variants)=>variants[((item?.variant||0)+Number(displayWeek||0)+offset)%variants.length];
    $: liveStories=(()=>{const s=[];
        if(upset)s.push({label:'🚨 Upset Brewing',text:storyPick(upset,0,[`${upset.leader.team.name} has the favorite on the ropes. ${upset.favorite.team.name} was supposed to control this matchup, but one more swing could turn this into Week ${displayWeek}'s headline upset.`,`${upset.leader.team.name} is threatening to blow up the projections. ${upset.favorite.team.name} entered with the edge, but the underdog is writing a very different story on the scoreboard.`,`Upset alarms are ringing around the GGL. ${upset.leader.team.name} has flipped the script on ${upset.favorite.team.name}, and the projected favorite is officially under pressure.`,`${upset.favorite.team.name} has a problem: ${upset.leader.team.name} is refusing to play the role of underdog. The favorite is chasing now, and this matchup has become must-watch territory.`])});
        const blow=[...updates].filter(i=>i.margin>=30).sort((a,b)=>b.margin-a.margin)[0];if(blow)s.push({label:'💥 Blowout Developing',text:storyPick(blow,1,[`${blow.leader.team.name} is delivering the week's biggest beatdown at ${blow.margin} points. ${blow.trailer.team.name} needs a miracle-sized response before this becomes a full-on humiliation.`,`${blow.leader.team.name} is running away with it. The gap has reached ${blow.margin}, leaving ${blow.trailer.team.name} searching for anything that can stop the bleeding.`,`This is getting ugly. ${blow.leader.team.name} has opened a ${blow.margin}-point crater and ${blow.trailer.team.name} is staring at the kind of deficit that can define an entire fantasy week.`,`${blow.leader.team.name} has turned the scoreboard into a warning sign for the rest of the league. A ${blow.margin}-point lead has ${blow.trailer.team.name} on the edge of a complete collapse.`])});
        const comeback=updates.find(i=>i.favorite&&i.leader&&i.favorite!==i.leader&&i.margin>=8);if(comeback)s.push({label:'🔥 Comeback Watch',text:storyPick(comeback,2,[`${comeback.favorite.team.name} was expected to be in control, but now the favorite is staring at a ${comeback.margin}-point hole. Every remaining starter is suddenly part of a comeback attempt.`,`${comeback.favorite.team.name} has been knocked backward, not out. The projected favorite trails by ${comeback.margin}, and the rest of this matchup has become a rescue mission.`,`The comeback clock is ticking for ${comeback.favorite.team.name}. Down ${comeback.margin} to ${comeback.leader.team.name}, the favorite needs its remaining lineup to start delivering immediately.`,`${comeback.leader.team.name} has forced ${comeback.favorite.team.name} into chase mode. The favorite is ${comeback.margin} points behind, and every point from here carries a little more pressure.`])});
        if(closest&&closest.margin<=7)s.push({label:'👀 One to Watch',text:storyPick(closest,3,[`${closest.teamOne.name} and ${closest.teamTwo.name} are separated by only ${closest.margin}. This is the matchup where one touchdown could change everything instantly.`,`Do not look away from ${closest.teamOne.name} vs ${closest.teamTwo.name}. Just ${closest.margin} points separate them, and this one could flip on a single play.`,`The tightest rope in the league belongs to ${closest.teamOne.name} and ${closest.teamTwo.name}. With only ${closest.margin} between them, every scoring update matters.`,`${closest.teamOne.name} vs ${closest.teamTwo.name} has become pure fantasy chaos. The margin is only ${closest.margin}, leaving both sides one big performance away from taking command.`])});
        if(topPlayer&&topPlayer.projection>0&&topPlayer.points>=topPlayer.projection+10){const v=(Number(displayWeek||0)+Math.floor(topPlayer.points))%4;s.push({label:'🏆 Statement Performance',text:[`${topPlayer.name} is wrecking expectations with ${topPlayer.points}, already ${numericRound(topPlayer.points-topPlayer.projection)} above projection and single-handedly reshaping the matchup.`,`${topPlayer.name} is putting on a show. ${topPlayer.points} points has smashed the projection by ${numericRound(topPlayer.points-topPlayer.projection)}, turning one lineup spot into a weekly headline.`,`${topPlayer.name} has gone nuclear. Sitting at ${topPlayer.points} points and ${numericRound(topPlayer.points-topPlayer.projection)} above projection, this performance is bending the entire matchup around it.`,`${topPlayer.name} is making a statement the whole league can see. ${topPlayer.points} points has blown past expectations and become one of Week ${displayWeek}'s defining performances.`][v]});}
        return s.slice(0,4);})();
    $: liveVerdict=(()=>{if(!updates.length)return'';const s=[];if(highest)s.push(`${highest.team.name} is setting the league's scoring pace at ${highest.points} and forcing everyone else to chase`);if(upset)s.push(`${upset.leader.team.name} has projected favorite ${upset.favorite.team.name} in real upset danger`);if(closest&&closest.margin<=7)s.push(`${closest.teamOne.name} vs ${closest.teamTwo.name} is hanging by a thread with almost no margin for error`);return s.length?`Week ${displayWeek} is starting to get loud: ${s.join('; ')}. The scoreboard can still turn, but right now these are the pressure points threatening to define the entire week.`:`Week ${displayWeek} is still waiting for somebody to seize the spotlight, but the board is starting to tighten.`;})();
</script>
<style>.liveCard{width:95%;max-width:900px;margin:0 auto 24px;padding:20px;box-sizing:border-box;border:1px solid var(--ccc);border-radius:16px;background:var(--fff);box-shadow:0 4px 14px rgba(0,0,0,.06)}.header{text-align:center;margin-bottom:16px}.eyebrow{font-size:.72rem;font-weight:800;letter-spacing:1px;text-transform:uppercase;opacity:.72}h4{margin:5px 0 0;font-size:1.35rem}.sub{margin-top:5px;font-size:.7rem;opacity:.62}.summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:16px}.summaryItem,.story,.game{padding:12px;border-radius:12px;background:var(--f3f3f3)}.label{font-size:.65rem;font-weight:800;text-transform:uppercase;letter-spacing:.4px;opacity:.72}.value{margin-top:4px;font-size:.86rem;font-weight:850}.stories,.games{display:grid;gap:10px}.stories{margin-bottom:16px}.storyText{margin-top:5px;font-size:.78rem;line-height:1.55;font-weight:600}.analysisTag{margin-bottom:9px;text-align:center;font-size:.68rem;font-weight:900;letter-spacing:.65px;opacity:1}.scoreLine{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:8px;font-weight:900}.teamOne{text-align:right}.teamTwo{text-align:left}.score{white-space:nowrap;font-size:1.08rem}.projections{margin-top:5px;text-align:center;font-size:.67rem;opacity:.7}.note{margin-top:11px;text-align:left;font-size:.8rem;line-height:1.6}.verdict{margin-top:16px;padding:15px;border:1px solid var(--ccc);border-radius:12px}.verdictTitle{font-size:.72rem;font-weight:900;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px}.verdictText{font-size:.82rem;line-height:1.55;font-weight:600}@media(max-width:600px){.liveCard{width:100%;padding:15px 12px}.scoreLine{font-size:.82rem}.score{font-size:1rem}.note,.storyText{font-size:.74rem}}</style>
{#if updates.length}<section class="liveCard"><div class="header"><div class="eyebrow">Live Week {displayWeek} Newsroom</div><h4>📰 GGL Live Desk</h4><div class="sub">The story changes as the Sleeper scoreboard changes</div></div><div class="summary"><div class="summaryItem"><div class="label">🔥 Hot Start</div><div class="value">{highest?.team?.name||'—'} · {highest?.points??0}</div></div><div class="summaryItem"><div class="label">⚔️ Game To Watch</div><div class="value">{closest?`${closest.teamOne.name} vs ${closest.teamTwo.name}`:'—'}</div></div><div class="summaryItem"><div class="label">⭐ {playerSpotlightLabel}</div><div class="value">{topPlayer?`${topPlayer.name} · ${topPlayer.points}`:'—'}</div></div><div class="summaryItem"><div class="label">🚨 Upset Watch</div><div class="value">{upset?`${upset.leader.team.name} over ${upset.favorite.team.name}`:'None yet'}</div></div></div>{#if liveStories.length}<div class="stories">{#each liveStories as story}<div class="story"><div class="label">{story.label}</div><div class="storyText">{story.text}</div></div>{/each}</div>{/if}<div class="games">{#each updates as item}<div class="game"><div class="analysisTag">{item.tag}</div><div class="scoreLine"><div class="teamOne">{item.teamOne.name}</div><div class="score">{item.scoreOne} – {item.scoreTwo}</div><div class="teamTwo">{item.teamTwo.name}</div></div><div class="projections">Pregame projection: {item.projectionOne} – {item.projectionTwo}</div><div class="note">{item.text}</div></div>{/each}</div>{#if liveVerdict}<div class="verdict"><div class="verdictTitle">📰 Live Newsroom Pulse</div><div class="verdictText">{liveVerdict}</div></div>{/if}</section>{/if}